  const FORMATION_PROJET_PRODUIT = {

    // ============================================================
    //  DELIVERY — Du mode projet au mode produit
    // ============================================================
    "projet-produit": {
      title: "Du mode projet au mode produit",
      icon: "&#128257;",
      color: "#f97316",
      track: "Delivery & Agilité",
      level: "Intermédiaire",
      duration: "4 à 5 h",
      defaultApp: APP.schemas,
      tagline: "Comprendre pourquoi tant d'organisations « agiles » fonctionnent encore en mode projet — et comment en sortir, y compris avec du réglementaire.",
      description: "Un parcours pour les PO de grands groupes où l'agilité reste plaquée sur une logique projet : ce qui distingue vraiment le mode produit, pourquoi le mode projet résiste (financement, gouvernance, comptabilité), son coût caché, le cas des équipes socles et des projets réglementaires (exemple de la directive crédit à la consommation), le financement Lean, le pilotage par la direction et les leviers d'action à portée d'un PO.",
      intro: "<p>Dans beaucoup de grands groupes, l'agilité a été déployée <em>dans les équipes</em> : sprints, daily, PI Planning, Product Owners. Mais le financement, la gouvernance et le critère de succès sont restés ceux du <strong>mode projet</strong> : un budget accordé pour un périmètre et une date, une équipe constituée pour l'occasion, un succès mesuré à « livré dans les temps et le budget », puis une bascule vers le run. Les équipes « socles » traitent les demandes des projets comme une file d'attente.</p><p>Ce n'est pas un échec des équipes : c'est la conséquence logique d'un système où <strong>l'argent et les décisions circulent par projet</strong>. Tant que ce système ne change pas, les cérémonies agiles n'y changent pas grand-chose.</p><p>Ce parcours vous aide à comprendre ce décalage, à le mesurer, et à agir à votre niveau. Il ne prétend pas que le mode projet doit disparaître partout : un projet réglementaire à date imposée garde des contraintes de projet. L'enjeu est de <strong>ne plus tout traiter comme un projet</strong>, et d'appliquer les bonnes pratiques de livraison même quand le cadre reste projet.</p>",
      chapters: [
        {
          slug: "pp-definitions",
          title: "Projet ou produit : de quoi parle-t-on vraiment ?",
          summary: "Ce qui distingue réellement les deux modes, et les symptômes d'une agilité plaquée sur une logique projet.",
          content: "<h4>Deux façons d'organiser le travail</h4><p>Dans son article de référence <em>Products Over Projects</em> (2018), Sriram Narayan (Thoughtworks) décrit le <strong>mode projet</strong> ainsi : le travail est financé au cas par cas ; il est réalisé par des équipes <em>temporaires</em>, dont les membres gardent leur rattachement hiérarchique ailleurs et sont puisés dans un « pool » de ressources considérées comme interchangeables. Le <strong>mode produit</strong> repose au contraire sur des équipes <em>durables</em> qui conçoivent, construisent et font tourner une solution autour d'un enjeu métier permanent.</p><div class='course-table-wrap'><table class='course-table'><thead><tr><th>Dimension</th><th>Mode projet</th><th>Mode produit</th></tr></thead><tbody><tr><td><strong>Financement</strong></td><td>Un budget par projet, pour un périmètre défini</td><td>Une capacité financée dans la durée (équipes, outils)</td></tr><tr><td><strong>Équipe</strong></td><td>Constituée pour le projet, dissoute à la fin</td><td>Stable, on lui apporte le travail</td></tr><tr><td><strong>Durée</strong></td><td>Début et fin définis</td><td>Aussi longtemps que le produit existe</td></tr><tr><td><strong>Critère de succès</strong></td><td>Délai, budget, périmètre respectés</td><td>Résultats obtenus : usage, satisfaction, revenus, coûts évités</td></tr><tr><td><strong>Périmètre</strong></td><td>Fixé au départ, tout changement est une « demande de changement »</td><td>Évolue en fonction de ce qu'on apprend</td></tr><tr><td><strong>Après la mise en production</strong></td><td>Bascule vers une équipe de run, l'équipe projet part</td><td>La même équipe continue : elle mesure, corrige, améliore</td></tr><tr><td><strong>Qui décide du contenu</strong></td><td>Le comité projet, sur la base du cahier des charges</td><td>L'équipe produit, dans un cadre d'objectifs</td></tr><tr><td><strong>Connaissance</strong></td><td>Se disperse à la fin du projet</td><td>S'accumule dans l'équipe</td></tr></tbody></table></div><h4>Les symptômes d'une agilité « plaquée »</h4><p>On parle parfois de <strong>« water-scrum-fall »</strong> : un cadrage et une validation en cascade au début, des sprints au milieu, une recette et une mise en production en bloc à la fin. Signes typiques :</p><ul><li>Le backlog est un cahier des charges découpé en stories, figé dès le départ.</li><li>Le « Product Owner » est en réalité un chef de projet qui suit un planning et un budget.</li><li>La vélocité sert à prévoir la date de fin du projet, pas à améliorer le flux.</li><li>Les démos se font entre l'équipe et le commanditaire, jamais avec de vrais utilisateurs.</li><li>L'équipe est dissoute ou réaffectée après la mise en production.</li><li>Personne ne mesure l'usage de ce qui a été livré.</li><li>Les équipes socles reçoivent des demandes des projets et les traitent dans une file d'attente.</li></ul><h4>Ce qui n'est pas en cause</h4><p>Le mode projet n'est pas « mauvais » par nature. Il est adapté quand le résultat attendu est clair et stable, l'incertitude faible, et qu'il existe une vraie fin (un déménagement de datacenter, par exemple). Le problème apparaît quand <strong>tout</strong> est traité comme un projet, y compris le développement de produits numériques, où l'incertitude sur la valeur est forte et où il n'y a jamais vraiment de « fin ».</p><div class='callout callout-tip'><strong>Réflexe PO :</strong> demandez-vous ce qui arrivera à votre équipe et à votre produit six mois après la prochaine mise en production. Si la réponse est « l'équipe passe à un autre projet et plus personne ne regarde les chiffres d'usage », vous êtes en mode projet, quel que soit le vocabulaire.</div>" + sources([S.fowler]),
          keyPoints: ["Mode projet : financement au cas par cas, équipes temporaires et interchangeables, succès = délai/budget", "Mode produit : équipes durables qui conçoivent, construisent et font tourner, succès = résultats", "Water-scrum-fall : cadrage en cascade, sprints au milieu, recette et MEP en bloc", "Le mode projet est adapté à certains cas ; le problème est de tout traiter comme un projet"],
          exercise: {
            title: "Diagnostiquer le mode de fonctionnement réel de votre équipe",
            brief: "Évaluez honnêtement si votre équipe fonctionne en mode projet, en mode produit ou entre les deux, sur chaque dimension du chapitre.",
            steps: [
              "Pour chacune des 8 dimensions du tableau, positionnez votre équipe sur une échelle de 1 (projet pur) à 5 (produit pur), avec un exemple concret.",
              "Comptez les symptômes de water-scrum-fall présents dans votre contexte.",
              "Dans Schémas & Workflows, dessinez le cycle de vie de votre dernière livraison importante : d'où venait le budget, qui a décidé du contenu, qu'est devenue l'équipe après.",
              "Identifiez les 2 dimensions les plus « projet » et ce qui les maintient ainsi.",
              "Faites le même exercice avec un collègue d'une autre équipe et comparez."
            ],
            deliverable: "Un profil de votre équipe sur les 8 dimensions, étayé par des exemples, et les 2 dimensions à travailler en priorité.",
            checklist: ["Chaque note est justifiée par un fait", "Le cycle de vie d'une livraison réelle est représenté", "Les causes des dimensions « projet » sont identifiées", "Le diagnostic a été confronté à un regard extérieur"]
          }
        },
        {
          slug: "pp-resistances",
          title: "Pourquoi le mode projet résiste : argent, gouvernance, structures",
          summary: "Les mécanismes qui maintiennent le mode projet même après une « transformation agile » : budget, comités, comptabilité, contrats, carrières.",
          content: "<h4>On a transformé les équipes, pas le système</h4><p>La plupart des transformations agiles en grand groupe commencent par les équipes : formation, cérémonies, nouveaux rôles. Mais les mécanismes qui déterminent réellement ce qui est fait — <strong>qui finance, qui décide, comment on mesure le succès</strong> — restent inchangés. Or, dans une organisation, le travail suit l'argent. Tant que l'argent est attribué par projet, le travail s'organise en projets.</p><h4>Les mécanismes qui maintiennent le mode projet</h4><div class='course-table-wrap'><table class='course-table'><thead><tr><th>Mécanisme</th><th>Comment il entretient le mode projet</th></tr></thead><tbody><tr><td><strong>Budget annuel par projet</strong></td><td>Pour obtenir de l'argent, il faut présenter un projet avec un périmètre, un coût et un gain. Ce périmètre devient ensuite un engagement.</td></tr><tr><td><strong>Comités d'engagement</strong></td><td>Chaque projet est validé, suivi et clôturé par un comité. Le suivi porte sur le consommé et le reste à faire, pas sur la valeur.</td></tr><tr><td><strong>Business case en amont</strong></td><td>Le gain est promis avant de construire, rarement vérifié après. On est jugé sur la livraison, pas sur le gain.</td></tr><tr><td><strong>Comptabilité (CapEx / OpEx)</strong></td><td>La capitalisation des coûts de développement est souvent calée sur des projets avec un début et une fin. Le travail continu d'une équipe produit semble plus difficile à capitaliser.</td></tr><tr><td><strong>Contrats avec les prestataires</strong></td><td>Les forfaits au périmètre figé reproduisent la logique projet chez les sous-traitants.</td></tr><tr><td><strong>Organisation matricielle</strong></td><td>Les personnes dépendent d'un pôle de compétences et sont « staffées » sur des projets : elles restent interchangeables.</td></tr><tr><td><strong>Carrières et reconnaissance</strong></td><td>Piloter un gros projet est valorisé ; faire vivre un produit dans la durée l'est moins.</td></tr><tr><td><strong>Séparation build / run</strong></td><td>Les équipes qui construisent ne sont pas celles qui font tourner : la responsabilité s'arrête à la mise en production.</td></tr></tbody></table></div><h4>La loi de Conway</h4><p>Selon la loi de Conway, les systèmes produits par une organisation reflètent sa structure de communication. Une organisation découpée en projets et en équipes socles produit des systèmes fragmentés, avec des interfaces aux endroits où les équipes se passent le relais — et donc des dépendances permanentes.</p><h4>Ce que dit SAFe… et ce qui est rarement appliqué</h4><p>SAFe prévoit explicitement la réponse : la <strong>Lean Portfolio Management</strong> et les <strong>Lean Budgets</strong>, qui financent des <em>chaînes de valeur</em> plutôt que des projets (chapitre 7). C'est souvent la partie du framework la moins mise en œuvre, parce qu'elle touche à la direction financière, aux processus budgétaires et à la répartition du pouvoir. Beaucoup d'organisations ont ainsi adopté les trains et les PI Planning… alimentés par des projets.</p><div class='callout callout-warn'><strong>Attention :</strong> ces mécanismes ne relèvent pas de la mauvaise volonté. Ils répondent à des besoins légitimes : contrôle des dépenses, arbitrage entre investissements, conformité comptable, visibilité pour la direction. Pour les faire évoluer, il faut proposer une autre manière de répondre à ces besoins — pas simplement les dénoncer.</div><div class='callout callout-tip'><strong>Réflexe PO :</strong> pour comprendre votre contexte, suivez l'argent. Qui a financé votre travail actuel, sur quelle base, et qui juge si c'est un succès ? C'est là que se trouvent les vrais leviers.</div>" + sources([S.fowler, S.leanBudgets, S.kersten]),
          keyPoints: ["Le travail suit l'argent : financer par projet produit du travail en projets", "Budget annuel, comités, business case, CapEx, forfaits, matriciel, carrières entretiennent le mode projet", "Loi de Conway : l'organisation en projets et socles se retrouve dans l'architecture", "SAFe propose les Lean Budgets, mais c'est la partie la moins appliquée"],
          exercise: {
            title: "Suivre l'argent et les décisions d'une initiative",
            brief: "Retracez le circuit financier et décisionnel d'une initiative récente de votre périmètre pour identifier les mécanismes qui la maintiennent en mode projet.",
            steps: [
              "Choisissez une initiative de digitalisation récente ou en cours.",
              "Dans Schémas & Workflows, représentez son circuit : demande initiale, business case, comité, budget, constitution de l'équipe, jalons, mise en production, clôture.",
              "Marquez chaque point où une décision est prise, et par qui.",
              "Indiquez à quel moment la valeur réelle (usage, gain) a été mesurée — si elle l'a été.",
              "Pour chaque mécanisme du tableau présent dans le circuit, notez le besoin légitime auquel il répond."
            ],
            deliverable: "Un schéma du circuit financier et décisionnel de l'initiative, avec les mécanismes identifiés et le besoin légitime de chacun.",
            checklist: ["Le circuit va de la demande à la clôture", "Les points de décision et leurs acteurs sont identifiés", "La mesure (ou l'absence de mesure) de la valeur est visible", "Chaque mécanisme est relié au besoin qu'il sert"]
          }
        },
        {
          slug: "pp-cout-cache",
          title: "Le coût caché du mode projet — et comment le rendre visible",
          summary: "Pertes de connaissance, files d'attente, gros lots, valeur jamais mesurée : ce que coûte le mode projet, et les métriques de flux pour le démontrer.",
          content: "<h4>Ce que le mode projet optimise… et ce qu'il ignore</h4><p>Le mode projet optimise ce qu'il mesure : le respect du délai, du budget et du périmètre. Mais Mik Kersten, dans <em>Project to Product</em> (2018), souligne qu'il laisse dans l'angle mort ce qui compte pour un produit numérique : le flux de valeur jusqu'au client, et ce que cette valeur produit réellement.</p><h4>Les coûts invisibles</h4><ul><li><strong>La perte de connaissance</strong> — à la fin du projet, l'équipe se disperse. La compréhension fine du métier, du code et des choix de conception part avec elle. L'équipe suivante recommence à apprendre.</li><li><strong>Les gros lots</strong> — un projet livre souvent en bloc en fin de parcours. Les erreurs d'interprétation sont découvertes en recette, quand elles coûtent le plus cher.</li><li><strong>Les files d'attente</strong> — chaque projet dépend d'équipes socles, de comités, de validations. Le travail passe plus de temps à attendre qu'à avancer.</li><li><strong>La valeur jamais vérifiée</strong> — le projet est clôturé à la mise en production ; personne n'est chargé de vérifier que le gain promis dans le business case a été atteint.</li><li><strong>Le produit orphelin</strong> — après le projet, le produit n'a plus d'équipe dédiée. Il accumule de la dette jusqu'au prochain « projet de refonte ».</li><li><strong>Le coût des démarrages</strong> — cadrage, constitution d'équipe, montée en compétence, contractualisation : répétés à chaque projet.</li></ul><h4>Les métriques de flux pour le démontrer</h4><p>Le <strong>Flow Framework</strong> de Mik Kersten propose de mesurer le flux de valeur à travers quatre types d'éléments de travail — les <strong>features</strong> (nouvelle valeur), les <strong>défauts</strong> (qualité), les <strong>risques</strong> (sécurité, conformité, réglementaire) et la <strong>dette</strong> — et cinq métriques :</p><div class='course-table-wrap'><table class='course-table'><thead><tr><th>Métrique</th><th>Question</th><th>Ce qu'elle révèle en mode projet</th></tr></thead><tbody><tr><td><strong>Flow Time</strong></td><td>Combien de temps entre le début du travail et sa livraison ?</td><td>Des délais longs, souvent dominés par l'attente</td></tr><tr><td><strong>Flow Efficiency</strong></td><td>Quelle part de ce temps est du travail actif ?</td><td>Souvent très faible : le travail attend les comités, les socles, la recette</td></tr><tr><td><strong>Flow Load</strong></td><td>Combien d'éléments sont en cours simultanément ?</td><td>Trop de travail en parallèle, chacun avance lentement</td></tr><tr><td><strong>Flow Velocity</strong></td><td>Combien d'éléments sont terminés par période ?</td><td>Un débit irrégulier, concentré en fin de projet</td></tr><tr><td><strong>Flow Distribution</strong></td><td>Quelle part du travail va aux features, défauts, risques, dette ?</td><td>La dette est systématiquement sacrifiée, le réglementaire arrive en urgence</td></tr></tbody></table></div><p>La <strong>Flow Efficiency</strong> est souvent la plus parlante : quand on découvre qu'une demande a passé 8 semaines dans le circuit pour 5 jours de travail effectif, la discussion sur l'organisation change de nature.</p><div class='callout callout-tip'><strong>Réflexe PO :</strong> les chiffres portent plus loin que les principes. Avant de plaider pour le mode produit, mesurez le temps réel d'une demande de bout en bout et sa part d'attente. C'est un argument que personne ne peut qualifier de dogmatique.</div>" + sources([S.kersten, S.fowler]),
          keyPoints: ["Le mode projet optimise délai/budget/périmètre et ignore le flux de valeur", "Coûts cachés : perte de connaissance, gros lots, files d'attente, valeur non vérifiée, produit orphelin", "Flow Framework : features, défauts, risques, dette — et 5 métriques de flux", "La Flow Efficiency (part de travail actif) est l'argument le plus parlant"],
          exercise: {
            title: "Mesurer la Flow Efficiency d'une demande réelle",
            brief: "Retracez le parcours d'une demande récente de bout en bout et calculez la part de travail actif par rapport au temps total.",
            steps: [
              "Choisissez une demande livrée récemment (une feature, une évolution) et retrouvez ses dates clés : expression du besoin, validations, début et fin des travaux, attente des socles, recette, mise en production.",
              "Dans Schémas & Workflows, représentez la chronologie en distinguant les périodes de travail actif et d'attente.",
              "Calculez : temps total (Flow Time), temps de travail actif, et Flow Efficiency = temps actif / temps total.",
              "Identifiez les 3 plus longues périodes d'attente et leur cause (comité, dépendance, recette, arbitrage).",
              "Estimez la Flow Distribution de votre équipe sur le dernier trimestre : part de features, défauts, risques/réglementaire, dette."
            ],
            deliverable: "La chronologie d'une demande avec sa Flow Efficiency, les 3 principales attentes et la Flow Distribution de l'équipe.",
            checklist: ["Les dates sont issues de faits (outils, mails, tickets)", "Attente et travail actif sont distingués", "Les causes d'attente sont nommées", "La distribution fait apparaître la part réelle de dette et de réglementaire"]
          }
        },
        {
          slug: "pp-mode-produit",
          title: "Ce qu'est un mode produit bien compris",
          summary: "Définir ses produits, des équipes durables et responsabilisées, la différence entre équipes produit et équipes de features, et l'exemple d'ING.",
          content: "<h4>Qu'est-ce qu'un « produit » dans un grand groupe ?</h4><p>Dans une banque, tout ne se vend pas à un client, mais tout peut être géré comme un produit. On distingue généralement :</p><ul><li><strong>Les produits clients</strong> — l'application mobile, le parcours de souscription en ligne, l'espace client.</li><li><strong>Les produits métiers internes</strong> — le poste de travail du conseiller, l'outil d'instruction des crédits.</li><li><strong>Les produits de plateforme</strong> — les services communs utilisés par d'autres équipes : référentiel client, moteur de paiement, API d'authentification.</li></ul><p>Un produit a des <strong>utilisateurs identifiés</strong>, un <strong>problème durable</strong> à résoudre, des <strong>indicateurs de résultat</strong> et une <strong>équipe responsable</strong> dans la durée. Dans SAFe, cela se traduit par l'organisation autour des <em>chaînes de valeur</em> : les trains sont constitués pour faire vivre des solutions, pas pour exécuter des projets.</p><h4>Équipes produit ou équipes de features ?</h4><p>Marty Cagan (SVPG) fait une distinction utile. Une <strong>équipe de features</strong> reçoit une liste de fonctionnalités à livrer : elle est jugée sur sa capacité à livrer. Une <strong>équipe produit</strong> reçoit un <em>problème à résoudre</em> et est jugée sur les résultats obtenus ; elle a la liberté — et la responsabilité — de trouver la bonne solution. Beaucoup d'organisations passées « en mode produit » ont en réalité des équipes de features stables : c'est un progrès (la connaissance reste), mais pas encore la destination.</p><div class='course-table-wrap'><table class='course-table'><thead><tr><th>Étape</th><th>Ce qui change</th></tr></thead><tbody><tr><td><strong>1. Équipes projet</strong></td><td>Équipes temporaires, périmètre imposé</td></tr><tr><td><strong>2. Équipes de features stables</strong></td><td>L'équipe dure, le travail vient à elle ; le contenu reste décidé ailleurs</td></tr><tr><td><strong>3. Équipes produit</strong></td><td>L'équipe reçoit des objectifs de résultat et choisit comment les atteindre</td></tr></tbody></table></div><h4>L'exemple d'ING</h4><p>En 2015, la banque néerlandaise ING a réorganisé son siège aux Pays-Bas selon un modèle inspiré de Spotify : environ <strong>350 « squads »</strong> de neuf personnes réparties en <strong>13 « tribus »</strong>, réunissant des métiers auparavant séparés (marketing, gestion des produits, canaux, développement informatique). Les dirigeants interrogés par McKinsey en 2017 font état d'un meilleur time-to-market, d'un engagement accru des collaborateurs et de gains de productivité. Deux points méritent attention : la transformation a été portée par la direction générale et a commencé par <strong>environ 3 500 personnes du siège</strong>, en leur demandant de repostuler sur les nouveaux rôles ; et elle a touché la structure, pas seulement les rituels.</p><div class='callout callout-warn'><strong>Attention :</strong> copier le « modèle Spotify » ou celui d'ING (tribus, squads, chapters) sans changer le financement et la gouvernance reproduit le même problème avec de nouveaux noms. Les intitulés ne font pas le mode produit ; les mécanismes de décision, si.</div><div class='callout callout-tip'><strong>Réflexe PO :</strong> vérifiez que votre produit a une définition claire : qui l'utilise, quel problème il résout, comment on mesure son succès, et quelle équipe en est responsable dans deux ans. Si l'une de ces réponses manque, commencez par là.</div>" + sources([S.cagan, S.ing, S.fowler]),
          keyPoints: ["Trois familles de produits : clients, métiers internes, plateformes", "Un produit = des utilisateurs, un problème durable, des indicateurs, une équipe responsable", "Cagan : équipe de features (livre une liste) vs équipe produit (résout un problème)", "ING (2015) : 350 squads, 13 tribus — une transformation de structure portée par la direction"],
          exercise: {
            title: "Cartographier les produits de votre périmètre",
            brief: "Identifiez les produits de votre périmètre, leurs utilisateurs, leurs indicateurs et l'équipe responsable — et repérez les trous.",
            steps: [
              "Dans Schémas & Workflows, listez les produits de votre périmètre en 3 familles : clients, métiers internes, plateformes.",
              "Pour chaque produit, notez : utilisateurs, problème résolu, 1 à 2 indicateurs de résultat, équipe responsable.",
              "Reliez les produits entre eux selon leurs dépendances (qui utilise quoi).",
              "Repérez les produits orphelins (sans équipe durable) et ceux sans indicateur de résultat.",
              "Situez chaque équipe sur les 3 étapes : projet, features stables, produit."
            ],
            deliverable: "Une carte des produits de votre périmètre avec utilisateurs, indicateurs, équipes et dépendances, et la liste des manques.",
            checklist: ["Les trois familles de produits sont représentées", "Chaque produit a (ou devrait avoir) un indicateur de résultat", "Les produits orphelins sont identifiés", "Chaque équipe est située sur l'échelle projet → produit"]
          }
        },
        {
          slug: "pp-equipes-socles",
          title: "Les équipes socles : de la file d'attente à la plateforme",
          summary: "Pourquoi les équipes socles deviennent des goulots, et comment Team Topologies aide à les transformer en plateformes au service des équipes produit.",
          content: "<h4>Le problème des socles « alimentés par les projets »</h4><p>Dans beaucoup de grands groupes, les équipes socles (référentiels, paiements, données, infrastructure, sécurité) fonctionnent comme des <strong>prestataires internes</strong> : chaque projet leur envoie des demandes, qu'elles traitent dans une file d'attente selon leur propre planning. Résultat : les équipes socles sont saturées et sans vision de leur propre produit, les équipes produit attendent, et toute initiative transverse devient une négociation.</p><h4>La grille de lecture de Team Topologies</h4><p>Matthew Skelton et Manuel Pais (<em>Team Topologies</em>, 2019) proposent quatre types d'équipes :</p><div class='course-table-wrap'><table class='course-table'><thead><tr><th>Type</th><th>Mission</th><th>Équivalent fréquent en grand groupe</th></tr></thead><tbody><tr><td><strong>Stream-aligned</strong></td><td>Alignée sur un flux de valeur (un produit, un parcours client) ; livre de bout en bout</td><td>Équipes produit / équipes des trains</td></tr><tr><td><strong>Platform</strong></td><td>Fournit des services internes en libre-service pour réduire la charge des équipes stream-aligned</td><td>Équipes socles… si elles fonctionnent en plateforme</td></tr><tr><td><strong>Enabling</strong></td><td>Aide temporairement d'autres équipes à acquérir une compétence</td><td>Experts sécurité, architecture, qualité, coachs</td></tr><tr><td><strong>Complicated-subsystem</strong></td><td>Porte un composant qui exige une expertise très spécialisée</td><td>Moteur de calcul de risque, cœur bancaire</td></tr></tbody></table></div><p>Ils décrivent aussi trois modes d'interaction : la <strong>collaboration</strong> (travailler ensemble, temporairement, sur un sujet nouveau), le <strong>« X-as-a-Service »</strong> (consommer un service sans avoir besoin de l'équipe qui le fournit) et la <strong>facilitation</strong> (une équipe en aide une autre à progresser).</p><h4>D'un socle « guichet » à une plateforme</h4><div class='course-table-wrap'><table class='course-table'><thead><tr><th>Socle « guichet »</th><th>Socle « plateforme »</th></tr></thead><tbody><tr><td>Reçoit des demandes au fil de l'eau</td><td>A sa propre roadmap, construite avec ses équipes utilisatrices</td></tr><tr><td>Chaque besoin est un développement spécifique</td><td>Propose des services standardisés en libre-service (API, documentation, environnements)</td></tr><tr><td>Priorise selon la pression politique</td><td>Priorise selon la valeur pour l'ensemble de ses utilisateurs</td></tr><tr><td>Mesuré au nombre de demandes traitées</td><td>Mesuré à l'autonomie qu'il donne aux équipes produit</td></tr><tr><td>Interactions : tickets et relances</td><td>Interactions : service, avec collaboration ponctuelle sur les nouveautés</td></tr></tbody></table></div><p>Une équipe socle en mode plateforme est elle-même une <strong>équipe produit</strong>, dont les clients sont les autres équipes : elle a un PO, des utilisateurs, une roadmap et des indicateurs.</p><h4>En attendant : gérer les dépendances explicitement</h4><p>La transformation d'un socle prend du temps. En attendant, les dépendances doivent être <strong>planifiées</strong> plutôt que subies : les représentants des équipes socles participent au PI Planning des trains qui dépendent d'eux, les dépendances sont visibles sur le tableau du programme, et les demandes récurrentes sont repérées comme candidates au libre-service.</p><div class='callout callout-warn'><strong>Attention :</strong> la solution n'est pas de supprimer les socles en redistribuant leurs compétences dans chaque équipe produit : on perdrait la mutualisation et la cohérence. L'objectif est de changer leur <em>mode d'interaction</em>, pas leur existence.</div><div class='callout callout-tip'><strong>Réflexe PO :</strong> listez les demandes que votre équipe a faites aux socles sur les trois derniers mois. Celles qui reviennent souvent sont des candidates au libre-service : proposez-les au PO du socle comme des besoins de produit, pas comme des tickets.</div>" + sources([S.teamTopo]),
          keyPoints: ["Les socles « alimentés par les projets » deviennent des files d'attente et des goulots", "Team Topologies : stream-aligned, platform, enabling, complicated-subsystem", "Trois interactions : collaboration, X-as-a-Service, facilitation", "Un socle en mode plateforme est une équipe produit dont les clients sont les autres équipes"],
          exercise: {
            title: "Classer vos équipes et leurs interactions",
            brief: "Appliquez la grille Team Topologies à votre périmètre et proposez une évolution pour une équipe socle.",
            steps: [
              "Dans Schémas & Workflows, placez les équipes de votre périmètre (produit et socles).",
              "Attribuez à chacune le type Team Topologies qui correspond à son fonctionnement réel, puis celui qu'elle devrait avoir.",
              "Représentez les interactions actuelles entre équipes et leur mode (tickets, collaboration, service, facilitation).",
              "Listez les demandes récurrentes de votre équipe vers un socle sur 3 mois.",
              "Proposez 2 services en libre-service que ce socle pourrait offrir, et les indicateurs qui mesureraient leur succès."
            ],
            deliverable: "Une carte des équipes avec types et modes d'interaction (actuels et cibles) et une proposition de 2 services en libre-service.",
            checklist: ["Chaque équipe a un type actuel et un type cible", "Les modes d'interaction sont explicites", "Les demandes récurrentes sont chiffrées", "Les services proposés réduisent réellement l'attente"]
          }
        },
        {
          slug: "pp-reglementaire",
          title: "Le réglementaire en mode produit : l'exemple d'une directive",
          summary: "Comment traiter un projet réglementaire à date imposée sans renoncer aux bonnes pratiques agiles — avec l'exemple de la directive crédit à la consommation (CCD2).",
          content: "<h4>Le cas le plus difficile… en apparence</h4><p>Un projet réglementaire semble être l'argument ultime en faveur du mode projet : une <strong>date imposée</strong> par la loi, un <strong>périmètre</strong> largement fixé par le texte, et aucune question sur l'opportunité de le faire. L'intérêt principal de l'agilité — découvrir ce qui a de la valeur — y compte effectivement peu.</p><p>Mais le vrai risque d'un projet réglementaire est rarement de rater le besoin. C'est <strong>l'intégration et la recette de fin de projet en bloc</strong>, avec la découverte tardive d'écarts d'interprétation, de cas non prévus ou d'impacts sur des systèmes oubliés. Sur ce risque-là, les pratiques agiles sont très utiles.</p><h4>L'exemple de la directive crédit à la consommation</h4><p>La directive (UE) <strong>2023/2225</strong> sur les contrats de crédit aux consommateurs (souvent appelée CCD2, ou DCC2 en français) remplace la directive de 2008. Les États membres devaient la transposer avant le 20 novembre 2025 ; en France, c'est l'objet de l'<strong>ordonnance n° 2025-880 du 3 septembre 2025</strong>. Les nouvelles règles s'appliquent à partir du <strong>20 novembre 2026</strong>.</p><p>Une telle directive n'est pas « un projet » : elle touche <strong>de nombreux produits à la fois</strong> — parcours de souscription en ligne et en agence, documents précontractuels, publicité, évaluation de la solvabilité, outils des conseillers, systèmes de gestion des contrats, reporting. C'est typiquement une initiative <em>transverse</em> à plusieurs trains et plusieurs équipes.</p><h4>Traiter le réglementaire comme un flux, pas comme une parenthèse</h4><ul><li><strong>C'est un type de travail normal.</strong> Dans le Flow Framework, le réglementaire fait partie des <em>risques</em>, au même titre que la sécurité. Il doit apparaître dans la distribution du travail de chaque équipe, pas arriver comme une urgence qui suspend tout le reste.</li><li><strong>C'est un epic de portefeuille avec une date ferme.</strong> Dans SAFe, une obligation transverse se porte au niveau du portefeuille et se décompose en features dans les backlogs des trains concernés, avec une date non négociable.</li><li><strong>On réserve de la capacité.</strong> Plutôt qu'une équipe projet constituée pour l'occasion, chaque équipe produit concernée réserve une part de sa capacité aux exigences qui touchent son produit — c'est elle qui connaît le mieux son système.</li><li><strong>On découpe par exigence et par produit.</strong> Chaque exigence de la directive × chaque produit concerné = un incrément livrable et vérifiable, plutôt qu'une livraison unique en fin de parcours.</li><li><strong>La conformité est dans la boucle en continu.</strong> L'interprétation du texte est la vraie source d'incertitude. Faire valider chaque incrément par les juristes et la conformité au fil de l'eau, c'est découvrir les écarts d'interprétation en semaines plutôt qu'en recette finale.</li><li><strong>On livre tôt, on active à la date.</strong> Les feature flags (voir le parcours CI/CD) permettent de déployer les changements en avance et de les activer le jour de l'entrée en application.</li><li><strong>Après l'échéance, l'obligation vit dans le produit.</strong> Les nouvelles règles deviennent des règles permanentes des produits concernés, portées par leurs équipes — pas un « projet clos » dont plus personne n'est responsable.</li></ul><div class='course-table-wrap'><table class='course-table'><thead><tr><th></th><th>Approche projet classique</th><th>Approche produit</th></tr></thead><tbody><tr><td><strong>Organisation</strong></td><td>Équipe projet dédiée, qui sollicite les équipes des produits concernés</td><td>Epic de portefeuille décliné dans les backlogs des équipes produit concernées</td></tr><tr><td><strong>Livraison</strong></td><td>Recette globale et mise en production en fin de projet</td><td>Incréments par exigence et par produit, déployés tôt, activés à la date</td></tr><tr><td><strong>Conformité</strong></td><td>Validation en fin de projet</td><td>Validation de chaque incrément au fil de l'eau</td></tr><tr><td><strong>Risque principal</strong></td><td>Découvrir les écarts trop tard</td><td>Mauvaise coordination entre équipes si l'epic est mal piloté</td></tr><tr><td><strong>Après l'échéance</strong></td><td>Projet clos, connaissance dispersée</td><td>Règles intégrées aux produits, équipes responsables</td></tr></tbody></table></div><div class='callout callout-warn'><strong>Attention :</strong> l'approche produit ne supprime pas le besoin de coordination. Une initiative réglementaire transverse a besoin d'un pilotage d'ensemble (un responsable de l'epic, un suivi des jalons, une vision consolidée pour la conformité et la direction). La différence : ce pilotage coordonne des équipes existantes au lieu de créer une structure parallèle.</div><div class='callout callout-tip'><strong>Réflexe PO :</strong> pour une obligation réglementaire qui touche votre produit, demandez à voir le texte ou sa synthèse par la conformité, découpez-le vous-même en exigences vérifiables pour votre produit, et proposez un calendrier de validations intermédiaires. Vous transformez un projet subi en travail maîtrisé.</div>" + sources([S.ccd2, S.ordonnance, S.kersten]),
          keyPoints: ["Le vrai risque d'un projet réglementaire : l'intégration et la recette en bloc, pas le besoin", "CCD2 (directive 2023/2225, ordonnance du 3 septembre 2025) s'applique au 20 novembre 2026 et touche de nombreux produits", "Réglementaire = type de travail normal (risque) : epic de portefeuille daté, capacité réservée dans les équipes produit", "Découper par exigence × produit, conformité dans la boucle, déployer tôt et activer à la date"],
          exercise: {
            title: "Découper une obligation réglementaire en incréments",
            brief: "Prenez une obligation réglementaire qui touche votre périmètre (CCD2 ou une autre) et construisez son plan de livraison en mode produit.",
            steps: [
              "Avec la conformité ou à partir d'une synthèse, listez 5 à 8 exigences du texte qui touchent votre périmètre.",
              "Croisez exigences et produits concernés : chaque croisement pertinent devient un incrément.",
              "Utilisez Story Splitter pour découper les incréments les plus gros en éléments livrables en moins d'une itération.",
              "Placez les incréments dans le temps avec des validations intermédiaires par la conformité, en gardant une marge avant la date d'application.",
              "Précisez quelle équipe produit porte chaque exigence après l'échéance."
            ],
            deliverable: "Une matrice exigences × produits, un plan d'incréments avec validations intermédiaires et la liste des équipes responsables après l'échéance.",
            checklist: ["Les exigences sont formulées de façon vérifiable", "Chaque incrément est livrable et testable seul", "La conformité valide au fil de l'eau, pas seulement à la fin", "Chaque règle a une équipe responsable après la date"],
            app: APP.story
          }
        },
        {
          slug: "pp-financement",
          title: "Financer des produits : budgets Lean et garde-fous",
          summary: "Financer une capacité plutôt qu'un périmètre, les garde-fous budgétaires de SAFe, et une transition progressive compatible avec le contrôle de gestion.",
          content: "<h4>Financer une capacité, pas un périmètre</h4><p>Le principe des <strong>Lean Budgets</strong> de SAFe est simple : au lieu de financer des projets, on finance les <strong>chaînes de valeur</strong> — c'est-à-dire une <em>capacité</em> (des équipes, leurs outils, leur infrastructure) dans la durée. La question passe de « combien coûte ce projet ? » à « combien de capacité voulons-nous investir sur ce produit ou ce domaine, et qu'attendons-nous en retour ? ».</p><p>Le coût d'une chaîne de valeur devient alors <strong>prévisible</strong> — c'est essentiellement le coût de ses équipes — et le contenu peut évoluer à l'intérieur de ce budget selon ce qu'on apprend.</p><h4>Les garde-fous : garder le contrôle sans tout valider</h4><p>Financer une capacité ne veut pas dire donner un chèque en blanc. SAFe définit des <strong>Lean Budget Guardrails</strong>, des règles qui encadrent l'usage du budget :</p><ul><li><strong>Une allocation de capacité explicite</strong> entre types de travail — nouvelles fonctionnalités, travaux d'architecture, réglementaire, dette, maintenance — pour éviter que le long terme soit systématiquement sacrifié.</li><li><strong>L'approbation des investissements importants</strong> : au-delà d'un seuil, une initiative (un epic de portefeuille) passe par un business case Lean et une décision explicite.</li><li><strong>Des horizons d'investissement</strong> équilibrés entre le cœur de métier actuel et les paris d'avenir.</li><li><strong>La participation continue des Business Owners</strong> aux événements de planification et de revue.</li></ul><h4>Le business case Lean</h4><p>Pour les grandes initiatives, le business case ne disparaît pas : il change de forme. Au lieu de promettre un gain précis sur un périmètre complet, il formule une <strong>hypothèse</strong>, définit un <strong>MVP</strong> et des <strong>indicateurs précurseurs</strong>, puis décide après le MVP de continuer, réorienter ou arrêter. On finance par étapes, sur preuves.</p><h4>Une transition progressive</h4><p>SAFe insiste sur le fait que le passage au financement par chaîne de valeur est une <strong>transition</strong>, pas une bascule. Une trajectoire réaliste en grand groupe :</p><ol><li><strong>Stabiliser les équipes</strong> tout en gardant le financement par projet : les projets viennent aux équipes, plutôt que l'inverse.</li><li><strong>Suivre les projets comme des epics</strong> dans les backlogs des trains, pour rendre visible le flux réel.</li><li><strong>Financer la capacité d'une chaîne de valeur pilote</strong> pour une année, avec des garde-fous et un suivi par résultats.</li><li><strong>Étendre</strong> progressivement, en ajustant les processus budgétaires avec la direction financière.</li></ol><h4>Et la comptabilité ?</h4><p>La capitalisation des coûts de développement (CapEx) est souvent citée comme un obstacle. En pratique, les règles comptables portent sur la nature du travail (développer un actif qui produira des avantages futurs), pas sur l'existence d'un « projet ». SAFe consacre d'ailleurs un article aux méthodes de capitalisation adaptées au travail agile. Le sujet se traite avec le contrôle de gestion et les commissaires aux comptes — c'est un chantier, pas un blocage.</p><div class='callout callout-warn'><strong>Attention :</strong> ne présentez pas les Lean Budgets à une direction financière comme « plus de liberté pour les équipes ». Présentez-les comme ce qu'ils sont aussi : une dépense <strong>plus prévisible</strong>, des arbitrages <strong>plus fréquents</strong> sur des preuves, et moins d'argent engagé sur des périmètres qui se révèlent inutiles.</div><div class='callout callout-tip'><strong>Réflexe PO :</strong> même sans changer le budget, proposez une allocation de capacité explicite pour votre équipe au prochain PI (par exemple : features, réglementaire, dette, défauts). Rendre visible ce partage est la première étape d'un garde-fou.</div>" + sources([S.leanBudgets, S.guardrails, S.vsFunding]),
          keyPoints: ["Lean Budgets : financer la capacité des chaînes de valeur, pas le périmètre des projets", "Garde-fous : allocation de capacité, approbation des grandes initiatives, horizons, Business Owners", "Business case Lean : hypothèse, MVP, indicateurs, décision par étapes", "Transition progressive : stabiliser les équipes, projets en epics, chaîne de valeur pilote, extension"],
          exercise: {
            title: "Proposer une allocation de capacité pour votre équipe",
            brief: "Construisez une proposition d'allocation de capacité et de garde-fous pour votre équipe ou votre train, présentable à votre management.",
            steps: [
              "À partir de la Flow Distribution mesurée au chapitre 3, décrivez la répartition actuelle du travail : features, réglementaire, défauts, dette.",
              "Proposez une répartition cible pour le prochain PI, en justifiant chaque part.",
              "Dans le Calculateur de Priorisation, priorisez les éléments de chaque catégorie à l'intérieur de sa part.",
              "Définissez le seuil au-delà duquel une initiative doit faire l'objet d'une décision explicite de la direction.",
              "Rédigez l'argumentaire en termes de prévisibilité et de contrôle, pour un public financier."
            ],
            deliverable: "Une proposition d'allocation de capacité (actuelle / cible), les garde-fous associés et un argumentaire d'une demi-page.",
            checklist: ["La répartition actuelle s'appuie sur des données", "Réglementaire et dette ont une part explicite", "Un seuil d'arbitrage par la direction est défini", "L'argumentaire parle de prévisibilité et de contrôle, pas seulement d'autonomie"],
            app: APP.prio
          }
        },
        {
          slug: "pp-pilotage",
          title: "Piloter et rendre des comptes en mode produit",
          summary: "Ce que la direction doit voir en mode produit : engagements datés, résultats, flux, risques — et comment remplacer le suivi « consommé / reste à faire ».",
          content: "<h4>La crainte légitime des directions</h4><p>« Si on ne pilote plus par projet, comment sait-on ce qui est fait ? » C'est l'objection la plus fréquente, et elle est légitime : une direction doit pouvoir arbitrer, anticiper et rendre compte. Le mode produit ne supprime pas la visibilité ; il <strong>change ce qu'on regarde</strong>.</p><h4>Du suivi de projet au suivi de produit</h4><div class='course-table-wrap'><table class='course-table'><thead><tr><th>Suivi en mode projet</th><th>Suivi en mode produit</th></tr></thead><tbody><tr><td>Budget consommé / reste à faire</td><td>Coût de la capacité par produit (stable et prévisible)</td></tr><tr><td>Avancement du périmètre en %</td><td>Ce qui a été livré ce PI, et ce qui est prévu au suivant</td></tr><tr><td>Respect des jalons</td><td>Respect des <strong>engagements datés</strong> (réglementaire, contractuel, dépendances)</td></tr><tr><td>Météo du projet (vert / orange / rouge)</td><td>Métriques de flux : délai, part d'attente, travail en cours, distribution</td></tr><tr><td>Livré / non livré</td><td>Résultats : usage, satisfaction, coûts évités, incidents</td></tr><tr><td>Clôture du projet</td><td>Décision périodique : continuer, réorienter ou réduire l'investissement</td></tr></tbody></table></div><h4>Un tableau de bord de direction en quatre blocs</h4><ol><li><strong>Engagements datés</strong> — les échéances non négociables (réglementaires, contractuelles) et leur niveau de confiance. C'est la partie qui ressemble le plus au suivi de projet, et c'est normal.</li><li><strong>Résultats</strong> — pour chaque produit, 2 ou 3 indicateurs de résultat et leur évolution.</li><li><strong>Flux</strong> — délai moyen, part d'attente, répartition du travail entre features, réglementaire, défauts et dette.</li><li><strong>Risques et arbitrages</strong> — ce qui nécessite une décision de la direction.</li></ol><h4>Des rituels de pilotage adaptés</h4><ul><li><strong>Les revues de portefeuille</strong> (Portfolio Sync dans SAFe) remplacent une partie des comités projet : elles arbitrent entre produits et initiatives sur la base des résultats et des flux.</li><li><strong>Le Kanban de portefeuille</strong> rend visibles toutes les grandes initiatives, de l'idée à la mise en œuvre, avec des limites de travail en cours.</li><li><strong>Les démos et revues de PI</strong> avec les Business Owners montrent le produit qui fonctionne, pas des slides d'avancement.</li></ul><div class='callout callout-warn'><strong>Attention :</strong> ne supprimez pas le suivi existant avant que le nouveau ait fait ses preuves. En transition, faites cohabiter les deux : le reporting projet habituel pour ceux qui en ont besoin, et le tableau de bord produit à côté. C'est quand la direction commence à regarder le second que le premier peut s'alléger.</div><div class='callout callout-tip'><strong>Réflexe PO :</strong> à votre prochain point avec votre management, ajoutez une seule information à votre reporting habituel : l'effet mesuré de ce qui a été livré le mois précédent. C'est le premier pas vers un pilotage par les résultats.</div>" + sources([S.leanBudgets, S.kersten]),
          keyPoints: ["Le mode produit ne supprime pas la visibilité, il change ce qu'on regarde", "Tableau de bord en 4 blocs : engagements datés, résultats, flux, risques et arbitrages", "Revues de portefeuille et Kanban de portefeuille remplacent une partie des comités projet", "En transition, faire cohabiter reporting projet et tableau de bord produit"],
          exercise: {
            title: "Reconcevoir le reporting de votre équipe",
            brief: "Transformez le reporting actuel de votre équipe ou de votre train en tableau de bord produit en quatre blocs.",
            steps: [
              "Rassemblez le reporting actuel (météo projet, avancement, budget).",
              "Pour chaque information actuelle, indiquez à quel besoin de la direction elle répond.",
              "Dans Schémas & Workflows, concevez le tableau de bord en 4 blocs : engagements datés, résultats, flux, risques et arbitrages.",
              "Vérifiez que chaque besoin de la direction identifié à l'étape 2 est couvert par le nouveau tableau de bord.",
              "Identifiez les données manquantes (indicateurs d'usage, métriques de flux) et comment les obtenir."
            ],
            deliverable: "Une maquette de tableau de bord produit en 4 blocs, la correspondance avec les besoins de la direction et la liste des données à collecter.",
            checklist: ["Les engagements datés restent visibles", "Chaque produit a des indicateurs de résultat", "Les besoins de la direction sont tous couverts", "Les données manquantes ont un plan de collecte"]
          }
        },
        {
          slug: "pp-agir",
          title: "Changer depuis l'intérieur : ce qu'un PO peut faire",
          summary: "Les leviers à portée d'un PO et d'une équipe, les étapes d'une transition réaliste, et les pièges à éviter.",
          content: "<h4>Être lucide sur ce qui se décide où</h4><p>Le passage au mode produit à l'échelle d'une organisation demande un <strong>sponsor</strong> au niveau de la direction, et en particulier de la direction financière : on ne change pas le processus budgétaire depuis une équipe. Mais attendre ce sponsor sans rien faire ne mène nulle part. Beaucoup de leviers sont à portée d'un PO — et ce sont eux qui produisent les preuves dont un sponsor aura besoin.</p><h4>Les leviers à votre portée</h4><div class='course-table-wrap'><table class='course-table'><thead><tr><th>Levier</th><th>Ce que vous pouvez faire</th></tr></thead><tbody><tr><td><strong>Rendre visible</strong></td><td>Mesurer le délai réel et la part d'attente d'une demande (chapitre 3) et les partager</td></tr><tr><td><strong>Livrer par morceaux</strong></td><td>Même dans un cadre projet, découper en livraisons intermédiaires et les montrer à de vrais utilisateurs</td></tr><tr><td><strong>Mesurer après la mise en production</strong></td><td>Proposer un indicateur d'usage pour chaque livraison et le suivre, même si personne ne le demande</td></tr><tr><td><strong>Défendre la stabilité de l'équipe</strong></td><td>Argumenter pour que le projet suivant vienne à l'équipe, plutôt que l'équipe soit dispersée</td></tr><tr><td><strong>Planifier les dépendances</strong></td><td>Faire venir les équipes socles au PI Planning et rendre les dépendances visibles</td></tr><tr><td><strong>Allouer la capacité</strong></td><td>Rendre explicite la part de dette et de réglementaire dans le travail de l'équipe</td></tr><tr><td><strong>Parler le langage des décideurs</strong></td><td>Présenter le mode produit en termes de prévisibilité, de risque et de coût, pas de principes agiles</td></tr></tbody></table></div><h4>Une trajectoire de transition réaliste</h4><ol><li><strong>Rendre visible</strong> — métriques de flux, coût des attentes, usage de ce qui est livré.</li><li><strong>Stabiliser les équipes</strong> — les projets viennent aux équipes.</li><li><strong>Définir les produits et leurs responsables</strong> — carte des produits, fin des produits orphelins.</li><li><strong>Transformer un socle en plateforme</strong> — en commençant par les demandes les plus récurrentes.</li><li><strong>Financer une chaîne de valeur pilote</strong> — avec des garde-fous et un pilotage par résultats.</li><li><strong>Étendre</strong> — sur la base des résultats du pilote.</li></ol><h4>Les pièges à éviter</h4><ul><li><strong>Renommer sans changer</strong> — appeler « produits » des projets et « PO » des chefs de projet.</li><li><strong>Réorganiser sans changer le financement</strong> — des tribus et des squads alimentées par des projets restent des équipes projet.</li><li><strong>Des équipes produit sans mandat</strong> — des équipes « responsables » d'un produit mais sans aucune latitude sur son contenu.</li><li><strong>Le big bang</strong> — une réorganisation massive sans preuve préalable. ING a réussi la sienne avec un engagement très fort de la direction générale ; sans cet engagement, mieux vaut procéder par pilotes.</li><li><strong>Tout vouloir en mode produit</strong> — certains travaux restent des projets (un déménagement, une migration ponctuelle). Le but est d'arrêter de traiter <em>tout</em> comme un projet.</li></ul><h4>Le lien avec l'IA</h4><p>Si votre organisation investit dans l'IA pour accélérer le développement, ce parcours est un prérequis. Plaquée sur du mode projet, l'IA accélère l'écriture des specs et du code, mais les goulots — comités, recette finale, dépendances aux socles, arbitrages — restent les mêmes. DORA le résume : l'IA amplifie l'organisation existante (voir le parcours « IA & SAFe »).</p><div class='callout callout-tip'><strong>Réflexe PO :</strong> choisissez un seul levier pour les trois prochains mois, mesurez son effet, et partagez le résultat. Une preuve locale convaincante vaut mieux qu'un plaidoyer général pour le mode produit.</div>" + sources([S.ing, S.vsFunding, S.dora2025, S.fowler]),
          keyPoints: ["Le changement global demande un sponsor, mais les leviers locaux produisent les preuves", "Leviers PO : rendre visible, livrer par morceaux, mesurer l'usage, stabiliser l'équipe, planifier les dépendances", "Trajectoire : visibilité → équipes stables → produits définis → socle plateforme → chaîne de valeur pilote", "Pièges : renommer sans changer, réorganiser sans changer le financement, équipes sans mandat, big bang"],
          exercise: {
            title: "Construire votre plan d'action sur trois mois",
            brief: "Choisissez les leviers les plus accessibles dans votre contexte et construisez un plan d'action mesurable.",
            steps: [
              "Dans Retro Board, listez avec votre équipe les irritants liés au mode projet (attentes, dispersion, recette tardive, absence de mesure).",
              "Associez chaque irritant à un levier du tableau.",
              "Choisissez 1 à 2 leviers accessibles sans décision de la direction.",
              "Dans Roadmap Designer, planifiez les actions sur 3 mois avec, pour chacune, l'indicateur qui montrera son effet.",
              "Identifiez le sponsor potentiel à qui présenter les résultats, et ce qui l'intéresse (coût, risque, délai)."
            ],
            deliverable: "Un plan d'action sur 3 mois avec 1 à 2 leviers, leurs indicateurs, et le sponsor visé.",
            checklist: ["Les irritants sont réels et partagés par l'équipe", "Les leviers choisis ne dépendent pas d'une décision de la direction", "Chaque action a un indicateur d'effet", "Le message au sponsor parle son langage"],
            app: APP.roadmap
          }
        }
      ]
    }

  };

  root.FORMATION_DATA = Object.assign({}, root.FORMATION_DATA || {}, FORMATION_PROJET_PRODUIT);
